import React, { useState } from 'react';

const EVENTS = [
  {
    title: 'Sports Day',
    description:
      'Celebrate Sports Day on June 15 in Seychelles with exciting games, teamwork, and community',
    date: 'June 15, 2025',
    status: 'upcoming',
    image: 'assets/sports.png',
    link: 'upcoming_event.html',
  },
  {
    title: 'Navratri',
    description:
      'Celebrate Navratri with vibrant dances, devotion, and cultural unity honoring the divine feminine.',
    date: 'June 25, 2025',
    status: 'completed',
    image: 'assets/deafult.png',
  },
  {
    title: 'Event Heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: 'assets/deafult.png',
  },
];

const statusColors = {
  upcoming: 'bg-blue-100 text-blue-500',
  completed: 'bg-orange-100 text-orange-500',
  ongoing: 'bg-yellow-100 text-yellow-600',
};

export default function EventsSection() {
  const [filter, setFilter] = useState('all');

  const filteredEvents =
    filter === 'all'
      ? EVENTS
      : EVENTS.filter((event) => event.status === filter);

  return (
    <main className="bg-white text-gray-800 font-sans min-h-screen">
      {/* Back Button */}
      <div className="p-6">
        <button
          onClick={() => history.back()}
          className="border rounded-full px-4 py-1 text-sm hover:bg-gray-100"
        >
          ⬅ Back To Home
        </button>
      </div>

      {/* Header */}
      <section className="text-center px-4">
        <h2 className="text-4xl font-bold mb-2">Our Events</h2>
        <p className="text-gray-600 max-w-xl mx-auto mb-6">
          Stay connected with our vibrant community. Discover celebrations,
          gatherings, and learning opportunities.
        </p>

        {/* Category Filters */}
        <div className="flex justify-center gap-4 mb-10">
          {['all', 'upcoming', 'completed', 'ongoing'].map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-4 py-2 rounded-full text-sm ${
                filter === status
                  ? 'bg-orange-500 text-white'
                  : 'text-gray-700 hover:bg-gray-100'
              }`}
            >
              {status.charAt(0).toUpperCase() + status.slice(1)}
            </button>
          ))}
        </div>

        {/* Events Grid */}
        <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
          {filteredEvents.map((event, idx) => {
            const colorClass = statusColors[event.status];
            const EventWrapper = event.link ? 'a' : 'div';
            return (
              <EventWrapper
                key={idx}
                href={event.link}
                className="bg-white rounded shadow p-4 text-left hover:shadow-md transition"
              >
                <img
                  src={event.image}
                  alt={`${event.title} image`}
                  className="rounded mb-4 w-full h-40 object-cover"
                />
                <h3 className="font-bold text-sm">{event.title}</h3>
                <p className="text-sm text-gray-600">{event.description}</p>
                <div className="flex justify-between items-center text-xs mt-3">
                  <span className="flex items-center gap-1">📅 {event.date}</span>
                  <span className={`px-2 py-0.5 rounded ${colorClass}`}>
                    {event.status}
                  </span>
                </div>
              </EventWrapper>
            );
          })}
        </div>

        {/* Pagination Placeholder */}
        <div className="mt-10 flex justify-center gap-2">
          {[1, 2, 3, 4].map((num) => (
            <button
              key={num}
              className="px-3 py-1 border rounded hover:bg-gray-100"
            >
              {num}
            </button>
          ))}
          <span className="px-3 py-1">...</span>
        </div>
      </section>
    </main>
  );
}
